def _sqlite_datetime_invalid(value: str) -> str:
    base = f"substr({value}, 1, 19)"
    return (
        f"typeof({value}) != 'text'\n"
        f"          OR instr({value}, char(0)) != 0\n"
        f"          OR length({value}) NOT IN (19, 26)\n"
        f"          OR substr({value}, 5, 1) != '-'\n"
        f"          OR substr({value}, 8, 1) != '-'\n"
        f"          OR substr({value}, 11, 1) != ' '\n"
        f"          OR substr({value}, 14, 1) != ':'\n"
        f"          OR substr({value}, 17, 1) != ':'\n"
        f"          OR substr({value}, 1, 4) GLOB '*[^0-9]*'\n"
        f"          OR substr({value}, 6, 2) GLOB '*[^0-9]*'\n"
        f"          OR substr({value}, 9, 2) GLOB '*[^0-9]*'\n"
        f"          OR substr({value}, 12, 2) GLOB '*[^0-9]*'\n"
        f"          OR substr({value}, 15, 2) GLOB '*[^0-9]*'\n"
        f"          OR substr({value}, 18, 2) GLOB '*[^0-9]*'\n"
        f"          OR substr({value}, 1, 4) = '0000'\n"
        f"          OR CAST(substr({value}, 12, 2) AS INTEGER) NOT BETWEEN 0 AND 23\n"
        f"          OR datetime({base}) IS NULL\n"
        f"          OR strftime('%Y-%m-%d %H:%M:%S', {base}) != {base}\n"
        f"          OR (length({value}) = 26 AND (\n"
        f"                 substr({value}, 20, 1) != '.'\n"
        f"                 OR substr({value}, 21, 6) GLOB '*[^0-9]*'\n"
        f"             ))"
    )


def _sqlite_text_invalid(value: str, *, maximum: int) -> str:
    return (
        f"typeof({value}) != 'text'\n"
        f"          OR instr({value}, char(0)) != 0\n"
        f"          OR length({value}) NOT BETWEEN 1 AND {maximum}"
    )


def _sqlite_digest_invalid(value: str) -> str:
    return (
        f"typeof({value}) != 'text'\n"
        f"          OR instr({value}, char(0)) != 0\n"
        f"          OR length({value}) != 71\n"
        f"          OR substr({value}, 1, 7) != 'sha256:'\n"
        f"          OR substr({value}, 8) GLOB '*[^0-9a-f]*'"
    )


def _sqlite_python_invalid(value: str) -> str:
    return (
        f"{_sqlite_text_invalid(value, maximum=64)}\n"
        f"          OR substr({value}, 1, 1) NOT GLOB '[a-z]'\n"
        f"          OR {value} GLOB '*[^a-z0-9_.-]*'"
    )


def _sqlite_cluster_session_invalid(value: str) -> str:
    return (
        f"{_sqlite_text_invalid(value, maximum=256)}\n"
        f"          OR length({value}) < 9\n"
        f"          OR substr({value}, 1, 8) != 'session_'\n"
        f"          OR substr({value}, 9, 1) NOT GLOB '[A-Za-z0-9]'\n"
        f"          OR substr({value}, 9) GLOB '*[^A-Za-z0-9_.-]*'"
    )


