def _install_evidence_fences(apps, schema_editor) -> None:
    vendor = schema_editor.connection.vendor
    if vendor == "postgresql":
        _install_postgresql_fences(apps, schema_editor)
    elif vendor == "sqlite":
        _install_sqlite_fences(apps, schema_editor)
    else:
        raise RuntimeError(
            "django-ray target execution evidence supports only SQLite and PostgreSQL"
        )


def _remove_evidence_fences(apps, schema_editor) -> None:
    evidence_table, outcome_table, *_ = _evidence_tables(apps, schema_editor)
    quote = schema_editor.quote_name
    vendor = schema_editor.connection.vendor
    if vendor == "postgresql":
        for trigger, table in (
            ("ray_tevid_guard_0026", evidence_table),
            ("ray_teout_guard_0026", outcome_table),
        ):
            schema_editor.execute(f"DROP TRIGGER IF EXISTS {quote(trigger)} ON {table}")
        for function in (
            "django_ray_guard_tevid_0026",
            "django_ray_guard_teout_0026",
        ):
            schema_editor.execute(f"DROP FUNCTION IF EXISTS {quote(function)}()")
    elif vendor == "sqlite":
        for trigger in (
            "ray_tevid_insert_0026",
            "ray_tevid_update_0026",
            "ray_teout_insert_0026",
            "ray_teout_update_0026",
        ):
            schema_editor.execute(f"DROP TRIGGER IF EXISTS {quote(trigger)}")
    else:
        raise RuntimeError(
            "django-ray target execution evidence supports only SQLite and PostgreSQL"
        )


def _guard_empty_evidence(apps, schema_editor) -> None:
    evidence_table, outcome_table, *_ = _evidence_tables(apps, schema_editor)
    vendor = schema_editor.connection.vendor
    if vendor == "postgresql":
        schema_editor.execute(
            f"LOCK TABLE {evidence_table}, {outcome_table} IN ACCESS EXCLUSIVE MODE"
        )
    elif vendor == "sqlite":
        schema_editor.execute(
            f"UPDATE {evidence_table} "
            "SET target_execution_evidence_id = target_execution_evidence_id WHERE 0"
        )
        schema_editor.execute(f"UPDATE {outcome_table} SET evidence_id = evidence_id WHERE 0")
    else:
        raise RuntimeError(
            "django-ray target execution evidence supports only SQLite and PostgreSQL"
        )
    alias = schema_editor.connection.alias
    if any(
        apps.get_model("django_ray", model_name).objects.using(alias).exists()
        for model_name in (
            "RayTaskTargetExecutionOutcome",
            "RayTaskTargetExecutionEvidence",
        )
    ):
        raise RuntimeError(
            "django-ray target execution evidence rollback requires both tables to be empty"
        )


